# First, let's find reviews that mention service
service_reviews = {}
for review in dataset:
    bid = review['business_id']
    text = review['text'].lower()
    # Check if the review mentions service
    if 'service' in text or 'staff' in text or 'employee' in text or 'worker' in text or 'crew' in text:
        if bid not in service_reviews:
            service_reviews[bid] = []
        service_reviews[bid].append(review)

print(f"Business IDs with service-related reviews: {len(service_reviews)}")
for bid, reviews in sorted(service_reviews.items(), key=lambda x: -len(x[1]))[:10]:
    print(f"  {bid}: {len(reviews)} reviews mentioning service")

