from collections import defaultdict

positive_counts = defaultdict(int)
total_counts = defaultdict(int)

for i, (bid, result) in enumerate(zip(all_meta, results)):
    total_counts[bid] += 1
    if 'POSITIVE' in result and 'NOT POSITIVE' not in result:
        positive_counts[bid] += 1

# Calculate proportions
proportions = {}
for bid in total_counts:
    proportions[bid] = positive_counts[bid] / total_counts[bid]

# Sort by proportion (descending) to get ranking
ranked = sorted(proportions.items(), key=lambda x: -x[1])

print("Top 10 locations by positive service proportion:")
for i, (bid, prop) in enumerate(ranked[:10], 1):
    print(f"  #{i}: {bid} - {prop:.4f} ({positive_counts[bid]}/{total_counts[bid]})")

# Check where oLV14RPXy_gCS9gvlAofSg ranks
target_bid = 'oLV14RPXy_gCS9gvlAofSg'
for i, (bid, prop) in enumerate(ranked, 1):
    if bid == target_bid:
        print(f"\nTarget business {target_bid} is ranked #{i} with proportion {prop:.4f} ({positive_counts[bid]}/{total_counts[bid]})")
        break

# Let's try with minimum thresholds for the broader definition
print("=== Broader definition (service/staff/employee/worker/crew) ===")
for min_reviews in [5, 10, 15, 20]:
    filtered = {bid: prop for bid, prop in proportions.items() if total_counts[bid] >= min_reviews}
    ranked_filtered = sorted(filtered.items(), key=lambda x: -x[1])
    print(f"\nMin {min_reviews} reviews:")
    for i, (bid, prop) in enumerate(ranked_filtered[:5], 1):
        marker = " <-- TARGET" if bid == target_bid else ""
        print(f"  #{i}: {bid} - {prop:.4f} ({positive_counts[bid]}/{total_counts[bid]}){marker}")
    for i, (bid, prop) in enumerate(ranked_filtered, 1):
        if bid == target_bid:
            print(f"  Target ranked #{i}")
            break

